const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const vm=require('node:vm');
const html=fs.readFileSync(path.join(__dirname,'../../index.html'),'utf8');
const planStart=html.indexOf('const PLAN = [');
const planEnd=html.indexOf('const PLAN_VERSION =',planStart);
assert(planStart>0&&planEnd>planStart);
const ctx={clone:structuredClone,parseNum:v=>Number(v)||0,fmtNum:String};
vm.createContext(ctx);
vm.runInContext(html.slice(planStart,planEnd),ctx);
const PLAN=vm.runInContext('PLAN',ctx);
const extraId='v5-thu-fly-extra',original=JSON.stringify(PLAN);
assert.equal(PLAN[3].ex.at(-1).exerciseId,extraId,'extra existe no Plano de quinta-feira');
assert.equal(PLAN[3].ex.at(-1).noDecision,true,'não passa a influenciar recomendações');
const start=html.indexOf(' // Apenas na primeira atualização: migra o auxiliar');
const end=html.indexOf(' // Mantém cardio planeado',start);
assert(start>0&&end>start);
vm.runInContext('this.normalisePlan=(s,PLAN,PLAN_VERSION)=>{'+html.slice(start,end)+'return s;}',ctx);
const legacy=structuredClone(PLAN);
legacy[3].ex.pop(); // estado anterior: Fly extra só existia no ecrã Treinar
legacy[3].ex[0].weight=72;
const state={profile:{planDeletedExerciseIds:[]},plano:legacy,planoVersion:5,sessions:[{date:'2026-11-05',dayIdx:3,ex:[{exerciseId:extraId,weight:14}]}]};
const history=JSON.stringify(state.sessions);
ctx.normalisePlan(state,PLAN,5);
assert.equal(state.plano[3].ex.at(-1).exerciseId,extraId);
assert.equal(state.plano[3].ex[0].weight,72,'migração não substitui cargas personalizadas');
assert.equal(state.profile.thursdayFlyExtraPlanReady,true);
assert.equal(JSON.stringify(state.sessions),history,'histórico inalterado');
ctx.normalisePlan(state,PLAN,5);
assert.equal(state.plano[3].ex.filter(e=>e.exerciseId===extraId).length,1,'não duplica em reaberturas');
const editStart=html.indexOf(' const setPlanEx = (di, xi, f, val) =>');
const editEnd=html.indexOf(' const setPlanName =',editStart);
const deleteStart=html.indexOf(' const delPlanEx = (di, xi) =>');
const deleteEnd=html.indexOf(' const reorderPlanEx =',deleteStart);
assert(editStart>0&&editEnd>editStart&&deleteStart>0&&deleteEnd>deleteStart);
ctx.update=fn=>{fn(state);ctx.normalisePlan(state,PLAN,5);};
Object.assign(ctx,{isAnchorExerciseName:()=>false,progressionCategory:()=> 'isolation',defaultProgressionStep:()=>({amount:2.5,kind:'kg',unit:'kg'})});
vm.runInContext(html.slice(editStart,editEnd)+'\nthis.edit=setPlanEx;',ctx);
vm.runInContext(html.slice(deleteStart,deleteEnd)+'\nthis.remove=delPlanEx;',ctx);
const ix=()=>state.plano[3].ex.findIndex(e=>e.exerciseId===extraId);
ctx.edit(3,ix(),'name','Fly direito personalizado');
ctx.edit(3,ix(),'sets','3');
assert.equal(state.plano[3].ex[ix()].name,'Fly direito personalizado');
assert.equal(state.plano[3].ex[ix()].sets,3);
assert.equal(state.plano[3].ex[ix()].decisionSourceExerciseId,'v5-thu-cable-fly','continua ligado enquanto não se edita a carga');
ctx.edit(3,ix(),'weight',17.5);
assert.equal(state.plano[3].ex[ix()].decisionSourceExerciseId,null,'editar carga desliga a ligação');
assert.equal(state.plano[3].ex[ix()].weight,17.5);
assert.equal(state.plano[3].ex[ix()].noDecision,true);
ctx.normalisePlan(state,PLAN,5);
assert.equal(state.plano[3].ex[ix()].weight,17.5,'edição sobrevive a reabertura');
ctx.remove(3,ix());
assert.equal(ix(),-1,'remoção imediata');
const reopened=JSON.parse(JSON.stringify(state));
ctx.normalisePlan(reopened,PLAN,5);
assert(!reopened.plano[3].ex.some(e=>e.exerciseId===extraId),'não reaparece após reabrir');
assert.equal(JSON.stringify(state.sessions),history,'remoção não elimina registos anteriores');
const other=PLAN[3].ex.find(e=>e.exerciseId==='v5-thu-rope-pushdown');
ctx.remove(3,state.plano[3].ex.findIndex(e=>e.exerciseId===other.exerciseId));
assert(!state.plano[3].ex.some(e=>e.exerciseId===other.exerciseId),'outros exercícios eliminados não reaparecem');
assert.equal(JSON.stringify(PLAN),original,'modelo base não é mutado');
assert(!html.includes('if(sel===3&&!loggerBaseExercises.some(x=>x.exerciseId==="v5-thu-fly-extra"))'),'Treinar já não injeta o exercício apagado');
console.log('Quinta: auxiliar editável, carga ligada/independente, eliminação persistente e Histórico intacto.');
